{"command":"python3 -c '
import glob, re

for f in sorted(glob.glob("/tmp/gen_ref/*/myservice/myservice.go")):
    content = open(f).read()
    print("File:", f)
    for m in re.finditer(r"type (\w+) struct \{([^}]+)\}", content):
        name = m.group(1)
        body = m.group(2)
        has_xmlname = "XMLName" in body
        first_line = body.strip().split("\n")[0] if body.strip() else ""
        if has_xmlname:
            print(f"  [XMLName] {name}: {first_line}")
'"}

