{"command":"cat << 'EOF' > soap/soap.go
package soap

import (
	"bytes"
	"context"
	"crypto/tls"
	"encoding/xml"
	"fmt"
	"io"
	"net"
	"net/http"
	"time"
)

type XSDDate string

func (d XSDDate) MarshalXML(e *xml.Encoder, start xml.StartElement) error {
	return e.EncodeElement(string(d), start)
}

func (d *XSDDate) UnmarshalXML(dec *xml.Decoder, start xml.StartElement) error {
	var v string
	if err := dec.DecodeElement(&v, &start); err != nil {
		return err
	}
	*d = XSDDate(v)
	return nil
}

type XSDDateTime string

func (dt XSDDateTime) MarshalXML(e *xml.Encoder, start xml.StartElement) error {
	return e.EncodeElement(string(dt), start)
}

func (dt *XSDDateTime) UnmarshalXML(dec *xml.Decoder, start xml.StartElement) error {
	var v string
	if err := dec.DecodeElement(&v, &start); err != nil {
		return err
	}
	*dt = XSDDateTime(v)
	return nil
}

type XSDTime string

func (t XSDTime) MarshalXML(e *xml.Encoder, start xml.StartElement) error {
	return e.EncodeElement(string(t), start)
}

func (t *XSDTime) UnmarshalXML(dec *xml.Decoder, start xml.StartElement) error {
	var v string
	if err := dec.DecodeElement(&v, &start); err != nil {
		return err
	}
	*t = XSDTime(v)
	return nil
}

type Client struct {
	url     string
	tls     bool
	headers []interface{}
	client  *http.Client
}

type Option func(*Client)

func WithTLS(tls *tls.Config) Option {
	return func(c *Client) {
		if tr, ok := c.client.Transport.(*http.Transport); ok {
			tr.TLSClientConfig = tls
		}
	}
}

func NewClient(url string, opts ...Option) *Client {
	c := &Client{
		url: url,
		client: &http.Client{
			Timeout: 30 * time.Second,
			Transport: &http.Transport{
				DialContext: (&net.Dialer{
					Timeout:   30 * time.Second,
					KeepAlive: 30 * time.Second,
				}).DialContext,
			},
		},
	}
	for _, opt := range opts {
		opt(c)
	}
	return c
}

func (c *Client) SetHeader(header interface{}) {
	c.headers = append(c.headers, header)
}

type SOAPEnvelope struct {
	XMLName xml.Name    `xml:"http://schemas.xmlsoap.org/soap/envelope/ Envelope"`
	Header  *SOAPHeader `xml:",omitempty"`
	Body    SOAPBody
}

type SOAPHeader struct {
	XMLName xml.Name      `xml:"http://schemas.xmlsoap.org/soap/envelope/ Header"`
	Headers []interface{} `xml:",omitempty"`
}

type SOAPBody struct {
	XMLName xml.Name    `xml:"http://schemas.xmlsoap.org/soap/envelope/ Body"`
	Fault   *SOAPFault  `xml:",omitempty"`
	Content interface{} `xml:",omitempty"`
}

type SOAPFault struct {
	XMLName xml.Name `xml:"http://schemas.xmlsoap.org/soap/envelope/ Fault"`
	Code    string   `xml:"faultcode,omitempty"`
	String  string   `xml:"faultstring,omitempty"`
	Actor   string   `xml:"faultactor,omitempty"`
	Detail  string   `xml:"detail,omitempty"`
}

func (f *SOAPFault) Error() string {
	return fmt.Sprintf("SOAP Fault: %s: %s", f.Code, f.String)
}

func (c *Client) Call(action string, request, response interface{}) error {
	return c.CallContext(context.Background(), action, request, response)
}

func (c *Client) CallContext(ctx context.Context, action string, request, response interface{}) error {
	env := SOAPEnvelope{
		Body: SOAPBody{
			Content: request,
		},
	}
	if len(c.headers) > 0 {
		env.Header = &SOAPHeader{Headers: c.headers}
	}

	buf := new(bytes.Buffer)
	if err := xml.NewEncoder(buf).Encode(env); err != nil {
		return err
	}

	req, err := http.NewRequestWithContext(ctx, "POST", c.url, buf)
	if err != nil {
		return err
	}

	req.Header.Set("Content-Type", "text/xml; charset=utf-8")
	if action != "" {
		req.Header.Set("SOAPAction", action)
	}

	res, err := c.client.Do(req)
	if err != nil {
		return err
	}
	defer res.Body.Close()

	if res.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(res.Body)
		return fmt.Sprintf("HTTP %d: %s", res.StatusCode, string(body))
	}

	respEnv := new(SOAPEnvelope)
	respEnv.Body.Content = response
	if err := xml.NewDecoder(res.Body).Decode(respEnv); err != nil {
		return err
	}

	if respEnv.Body.Fault != nil {
		return respEnv.Body.Fault
	}

	return nil
}
EOF
"}

