{"command":"cat << 'EOF' > wsdl/parser.go
package wsdl

import (
	"crypto/tls"
	"encoding/xml"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
)

type ParsedWSDL struct {
	Definitions Definitions
	RawWSDL     string
	Path        string
}

func ReadWSDL(location string, insecureSkipVerify bool) (*ParsedWSDL, error) {
	data, resolvedLoc, err := loadLocation(location, insecureSkipVerify)
	if err != nil {
		return nil, err
	}

	var def Definitions
	if err := xml.Unmarshal(data, &def); err != nil {
		return nil, err
	}

	pw := &ParsedWSDL{
		Definitions: def,
		RawWSDL:     string(data),
		Path:        resolvedLoc,
	}

	// Resolve schema imports and includes
	visited := make(map[string]bool)
	visited[resolvedLoc] = true

	var processSchema func(s *Schema, currentLoc string) error
	processSchema = func(s *Schema, currentLoc string) error {
		// Process includes
		for _, inc := range s.Includes {
			if inc.SchemaLocation == "" {
				continue
			}
			targetLoc := resolveRefLocation(currentLoc, inc.SchemaLocation)
			if visited[targetLoc] {
				continue
			}
			visited[targetLoc] = true

			incData, resLoc, err := loadLocation(targetLoc, insecureSkipVerify)
			if err != nil {
				return err
			}

			var incSchema Schema
			if err := xml.Unmarshal(incData, &incSchema); err != nil {
				return err
			}

			if incSchema.TargetNamespace == "" {
				incSchema.TargetNamespace = s.TargetNamespace
			}

			pw.Definitions.Types.Schemas = append(pw.Definitions.Types.Schemas, incSchema)
			if err := processSchema(&incSchema, resLoc); err != nil {
				return err
			}
		}

		// Process imports
		for _, imp := range s.Imports {
			if imp.SchemaLocation == "" {
				continue
			}
			targetLoc := resolveRefLocation(currentLoc, imp.SchemaLocation)
			if visited[targetLoc] {
				continue
			}
			visited[targetLoc] = true

			impData, resLoc, err := loadLocation(targetLoc, insecureSkipVerify)
			if err != nil {
				return err
			}

			var impSchema Schema
			if err := xml.Unmarshal(impData, &impSchema); err != nil {
				return err
			}

			if impSchema.TargetNamespace == "" {
				impSchema.TargetNamespace = imp.Namespace
			}

			pw.Definitions.Types.Schemas = append(pw.Definitions.Types.Schemas, impSchema)
			if err := processSchema(&impSchema, resLoc); err != nil {
				return err
			}
		}

		return nil
	}

	for i := range pw.Definitions.Types.Schemas {
		if err := processSchema(&pw.Definitions.Types.Schemas[i], resolvedLoc); err != nil {
			return nil, err
		}
	}

	return pw, nil
}

func isURL(loc string) bool {
	return strings.HasPrefix(loc, "http://") || strings.HasPrefix(loc, "https://")
}

func loadLocation(loc string, insecureSkipVerify bool) ([]byte, string, error) {
	if isURL(loc) {
		fmt.Printf("🍀  Downloading file %s\n", loc)
		client := &http.Client{}
		if insecureSkipVerify {
			tr := &http.Transport{
				TLSClientConfig: &tls.Config{InsecureSkipVerify: true},
			}
			client.Transport = tr
		}
		resp, err := client.Get(loc)
		if err != nil {
			return nil, loc, err
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			return nil, loc, fmt.Errorf("HTTP error: %s", resp.Status)
		}
		data, err := io.ReadAll(resp.Body)
		return data, loc, err
	} else {
		absPath, err := filepath.Abs(loc)
		if err != nil {
			absPath = loc
		}
		fmt.Printf("🍀  Reading file %s\n", absPath)
		data, err := os.ReadFile(absPath)
		if err != nil {
			return nil, absPath, err
		}
		return data, absPath, nil
	}
}

func resolveRefLocation(baseLoc, ref string) string {
	if isURL(ref) {
		return ref
	}
	if isURL(baseLoc) {
		u, err := url.Parse(baseLoc)
		if err != nil {
			return ref
		}
		rel, err := url.Parse(ref)
		if err != nil {
			return ref
		}
		return u.ResolveReference(rel).String()
	}
	if filepath.IsAbs(ref) {
		return ref
	}
	return filepath.Join(filepath.Dir(baseLoc), ref)
}
EOF
"}

