package main

import (
	"flag"
	"fmt"
	"os"

	"github.com/hooklift/gowsdl/generator"
	"github.com/hooklift/gowsdl/wsdl"
)

func main() {
	if len(os.Args) == 1 {
		printUsage()
		os.Exit(0)
	}

	dirFlag := flag.String("d", "./", "Directory under which package directory will be created")
	insecureFlag := flag.Bool("i", false, "Skips TLS Verification")
	makePublicFlag := flag.Bool("make-public", true, "Make the generated types public/exported")
	outFlag := flag.String("o", "myservice.go", "File where the generated code will be saved")
	pkgFlag := flag.String("p", "myservice", "Package under which code will be generated")
	versionFlag := flag.Bool("v", false, "Shows gowsdl version")

	flag.Usage = printUsage

	flag.Parse()

	if *versionFlag {
		fmt.Println("🍀  v0.5.0")
		os.Exit(0)
	}

	wsdlPath := os.Args[len(os.Args)-1]

	pw, err := wsdl.ReadWSDL(wsdlPath, *insecureFlag)
	if err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}

	opts := generator.Options{
		Pkg:        *pkgFlag,
		Outfile:    *outFlag,
		Dir:        *dirFlag,
		MakePublic: *makePublicFlag,
	}

	if err := generator.Generate(pw, opts); err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}

	fmt.Println("🍀  Done 👍")
}

func printUsage() {
	fmt.Fprintf(os.Stderr, "Usage: %s [options] myservice.wsdl\n", os.Args[0])
	flag.PrintDefaults()
}
EOF

