{"command":"cat << 'EOF' > generator/generator.go
package generator

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"text/template"
	"unicode"

	"github.com/hooklift/gowsdl/wsdl"
)

type Options struct {
	Pkg        string
	Outfile    string
	Dir        string
	MakePublic bool
}

type TypeModel struct {
	Name string
	Code string
}

type OperationModel struct {
	Name          string
	RequestType   string
	ResponseType  string
	SoapAction    string
	Documentation string
}

type PortTypeModel struct {
	InterfaceName string
	StructName    string
	Operations    []OperationModel
}

type ServerOperationModel struct {
	ReqType  string
	RespType string
}

type ClientData struct {
	PackageName string
	Types       []TypeModel
	PortTypes   []PortTypeModel
}

type ServerData struct {
	PackageName      string
	RawWSDL          string
	ServerOperations []ServerOperationModel
}

var goKeywords = map[string]bool{
	"break": true, "default": true, "func": true, "interface": true, "select": true,
	"case": true, "defer": true, "go": true, "map": true, "struct": true,
	"chan": true, "else": true, "goto": true, "package": true, "switch": true,
	"const": true, "fallthrough": true, "if": true, "range": true, "type": true,
	"continue": true, "for": true, "import": true, "return": true, "var": true,
}

func Generate(pw *wsdl.ParsedWSDL, opts Options) error {
	clientData := ClientData{
		PackageName: opts.Pkg,
	}

	serverData := ServerData{
		PackageName: opts.Pkg,
		RawWSDL:     pw.RawWSDL,
	}

	typeModels, elementToTypeMap := processTypes(pw, opts)
	clientData.Types = typeModels

	msgToType := make(map[string]string)
	for _, msg := range pw.Definitions.Messages {
		if len(msg.Parts) == 0 {
			fmt.Printf("🍀  [WARN] %s message doesn't have any parts, ignoring message...\n", msg.Name)
			continue
		}
		part := msg.Parts[0]
		rawName := ""
		if part.Element != "" {
			rawName = stripPrefix(part.Element)
		} else if part.Type != "" {
			rawName = stripPrefix(part.Type)
		}

		if mapped, ok := elementToTypeMap[rawName]; ok {
			msgToType[msg.Name] = mapped
		} else {
			msgToType[msg.Name] = exportName(rawName, opts.MakePublic)
		}
	}

	opToSoapAction := make(map[string]string)
	for _, b := range pw.Definitions.Bindings {
		for _, bo := range b.BindingOperations {
			action := bo.SoapOperation.SoapAction
			if action == "" {
				action = "''"
			}
			opToSoapAction[bo.Name] = action
		}
	}

	serverOpSet := make(map[string]bool)

	for _, pt := range pw.Definitions.PortTypes {
		ptModel := PortTypeModel{
			InterfaceName: exportName(pt.Name, opts.MakePublic),
			StructName:    unexportName(pt.Name, opts.MakePublic),
		}

		for _, op := range pt.Operations {
			reqMsg := stripPrefix(op.Input.Message)
			respMsg := stripPrefix(op.Output.Message)

			reqType, okReq := msgToType[reqMsg]
			respType, okResp := msgToType[respMsg]

			if !okReq || !okResp {
				continue
			}

			action := opToSoapAction[op.Name]
			if action == "" {
				action = "''"
			}

			doc := formatComment(op.Documentation, "")

			opModel := OperationModel{
				Name:          exportName(op.Name, opts.MakePublic),
				RequestType:   reqType,
				ResponseType:  respType,
				SoapAction:    action,
				Documentation: doc,
			}
			ptModel.Operations = append(ptModel.Operations, opModel)

			opKey := reqType + "->" + respType
			if !serverOpSet[opKey] {
				serverOpSet[opKey] = true
				serverData.ServerOperations = append(serverData.ServerOperations, ServerOperationModel{
					ReqType:  reqType,
					RespType: respType,
				})
			}
		}

		clientData.PortTypes = append(clientData.PortTypes, ptModel)
	}

	tmplClient, err := template.New("client").Parse(ClientTemplate)
	if err != nil {
		return err
	}
	var bufClient bytes.Buffer
	if err := tmplClient.Execute(&bufClient, clientData); err != nil {
		return err
	}

	formattedClient, err := format.Source(bufClient.Bytes())
	if err != nil {
		formattedClient = bufClient.Bytes()
	}

	tmplServer, err := template.New("server").Parse(ServerTemplate)
	if err != nil {
		return err
	}
	var bufServer bytes.Buffer
	if err := tmplServer.Execute(&bufServer, serverData); err != nil {
		return err
	}

	formattedServer, err := format.Source(bufServer.Bytes())
	if err != nil {
		formattedServer = bufServer.Bytes()
	}

	outPath := filepath.Join(opts.Dir, opts.Pkg, opts.Outfile)
	serverOutPath := filepath.Join(opts.Dir, opts.Pkg, "server"+filepath.Base(opts.Outfile))

	if err := writeFile(outPath, formattedClient); err != nil {
		return err
	}
	if err := writeFile(serverOutPath, formattedServer); err != nil {
		return err
	}

	return nil
}

func writeFile(path string, content []byte) error {
	return os.WriteFile(path, content, 0644)
}

func processTypes(pw *wsdl.ParsedWSDL, opts Options) ([]TypeModel, map[string]string) {
	var models []TypeModel
	elementToTypeMap := make(map[string]string)

	schemas := pw.Definitions.Types.Schemas

	topAttrs := make(map[string]wsdl.Attribute)
	elementToComplexTypeXMLName := make(map[string]string)

	for _, s := range schemas {
		targetNS := s.TargetNamespace
		for _, attr := range s.Attributes {
			if attr.Name != "" {
				topAttrs[attr.Name] = attr
			}
		}
		for _, el := range s.Elements {
			if el.Name != "" && el.Type != "" && !isBuiltinXSD(el.Type) {
				ctName := exportName(stripPrefix(el.Type), opts.MakePublic)
				xmlTag := fmt.Sprintf("%s %s", targetNS, el.Name)
				if targetNS == "" {
					xmlTag = el.Name
				}
				elementToComplexTypeXMLName[ctName] = xmlTag
			}
		}
	}

	for _, s := range schemas {
		targetNS := s.TargetNamespace

		// 1. SimpleTypes (FIRST)
		for _, st := range s.SimpleTypes {
			if st.Name == "" {
				continue
			}
			typeName := exportName(st.Name, opts.MakePublic)
			doc := ""
			if st.Annotation != nil {
				doc = formatComment(st.Annotation.Documentation, "")
			}

			if st.Restriction != nil && len(st.Restriction.Enumerations) > 0 {
				var enumLines []string
				for _, enum := range st.Restriction.Enumerations {
					enumVal := enum.Value
					constName := typeName + sanitizeEnumVal(enumVal)
					enumDoc := ""
					if enum.Annotation != nil && enum.Annotation.Documentation != "" {
						enumDoc = formatComment(enum.Annotation.Documentation, "\t") + "\n"
					}
					enumLines = append(enumLines, fmt.Sprintf("%s\t%s %s = %q", enumDoc, constName, typeName, enumVal))
				}

				code := fmt.Sprintf("type %s string\n\nconst (\n%s\n)", typeName, strings.Join(enumLines, "\n\n"))
				if doc != "" {
					code = fmt.Sprintf("// %s\ntype %s string\n\nconst (\n%s\n)", doc, typeName, strings.Join(enumLines, "\n\n"))
				}
				models = append(models, TypeModel{Name: typeName, Code: code})
			} else if st.Restriction != nil {
				base := mapXSDType(st.Restriction.Base)
				if base == "soap.XSDDateTime" || base == "soap.XSDDate" {
					code := fmt.Sprintf("type %s %s\n\nfunc (xdt %s) MarshalXML(e *xml.Encoder, start xml.StartElement) error {\n\treturn %s(xdt).MarshalXML(e, start)\n}\n\nfunc (xdt *%s) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {\n\treturn (*%s)(xdt).UnmarshalXML(d, start)\n}", typeName, base, typeName, base, typeName, base)
					models = append(models, TypeModel{Name: typeName, Code: code})
				} else {
					code := fmt.Sprintf("type %s %s", typeName, base)
					models = append(models, TypeModel{Name: typeName, Code: code})
				}
			}
		}

		// 2. Elements
		for _, el := range s.Elements {
			if el.Name == "" {
				continue
			}
			elemName := exportName(el.Name, opts.MakePublic)

			if el.ComplexType != nil {
				code := renderComplexType(*el.ComplexType, elemName, targetNS, opts, topAttrs)
				xmlNameTag := fmt.Sprintf("%s %s", targetNS, el.Name)
				if targetNS == "" {
					xmlNameTag = el.Name
				}
				code = injectXMLName(code, xmlNameTag)
				models = append(models, TypeModel{Name: elemName, Code: code})
			} else if el.SimpleType != nil {
				if el.SimpleType.Restriction != nil && len(el.SimpleType.Restriction.Enumerations) > 0 {
					var enumLines []string
					for _, enum := range el.SimpleType.Restriction.Enumerations {
						enumVal := enum.Value
						constName := elemName + sanitizeEnumVal(enumVal)
						enumDoc := ""
						if enum.Annotation != nil && enum.Annotation.Documentation != "" {
							enumDoc = formatComment(enum.Annotation.Documentation, "\t") + "\n"
						}
						enumLines = append(enumLines, fmt.Sprintf("%s\t%s %s = %q", enumDoc, constName, elemName, enumVal))
					}
					doc := ""
					if el.Annotation != nil {
						doc = formatComment(el.Annotation.Documentation, "")
					}
					code := fmt.Sprintf("type %s string\n\nconst (\n%s\n)", elemName, strings.Join(enumLines, "\n\n"))
					if doc != "" {
						code = fmt.Sprintf("// %s\ntype %s string\n\nconst (\n%s\n)", doc, elemName, strings.Join(enumLines, "\n\n"))
					}
					models = append(models, TypeModel{Name: elemName, Code: code})
				}
			} else if el.Type != "" {
				rawType := stripPrefix(el.Type)
				mappedType := mapXSDType(el.Type)

				if isBuiltinXSD(el.Type) {
					if mappedType == "soap.XSDDateTime" || mappedType == "soap.XSDDate" {
						code := fmt.Sprintf("type %s %s\n\nfunc (xdt %s) MarshalXML(e *xml.Encoder, start xml.StartElement) error {\n\treturn %s(xdt).MarshalXML(e, start)\n}\n\nfunc (xdt *%s) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {\n\treturn (*%s)(xdt).UnmarshalXML(d, start)\n}", elemName, mappedType, elemName, mappedType, elemName, mappedType)
						models = append(models, TypeModel{Name: elemName, Code: code})
					} else {
						code := fmt.Sprintf("type %s %s", elemName, mappedType)
						models = append(models, TypeModel{Name: elemName, Code: code})
					}
				} else {
					targetType := exportName(rawType, opts.MakePublic)
					elementToTypeMap[el.Name] = targetType
					if elemName != targetType {
						code := fmt.Sprintf("type %s %s", elemName, targetType)
						models = append(models, TypeModel{Name: elemName, Code: code})
					}
				}
			}
		}

		// 3. ComplexTypes
		for _, ct := range s.ComplexTypes {
			if ct.Name == "" {
				continue
			}
			typeName := exportName(ct.Name, opts.MakePublic)
			code := renderComplexType(ct, typeName, targetNS, opts, topAttrs)

			if xmlTag, ok := elementToComplexTypeXMLName[typeName]; ok {
				code = injectXMLName(code, xmlTag)
			}

			models = append(models, TypeModel{Name: typeName, Code: code})
		}
	}

	return models, elementToTypeMap
}

func getComplexTypeElements(ct wsdl.ComplexType) []wsdl.Element {
	var elems []wsdl.Element
	if ct.Sequence != nil {
		elems = append(elems, ct.Sequence.Elements...)
	}
	if ct.All != nil {
		elems = append(elems, ct.All.Elements...)
	}
	if ct.Choice != nil {
		elems = append(elems, ct.Choice.Elements...)
	}
	return elems
}

func renderComplexType(ct wsdl.ComplexType, typeName string, targetNS string, opts Options, topAttrs map[string]wsdl.Attribute) string {
	var fields []string

	elems := getComplexTypeElements(ct)

	if ct.ComplexContent != nil {
		if ct.ComplexContent.Extension != nil {
			ext := ct.ComplexContent.Extension
			baseType := exportName(stripPrefix(ext.Base), opts.MakePublic)
			fields = append(fields, fmt.Sprintf("\t*%s", baseType))
			if ext.Sequence != nil {
				elems = append(elems, ext.Sequence.Elements...)
			}
			if ext.All != nil {
				elems = append(elems, ext.All.Elements...)
			}
			if ext.Choice != nil {
				elems = append(elems, ext.Choice.Elements...)
			}
		}
	}

	for _, childEl := range elems {
		fieldName := exportName(childEl.Name, opts.MakePublic)
		fieldType := "string"
		isComplex := false

		if childEl.Type != "" {
			fieldType = mapXSDType(childEl.Type)
			if !isBuiltinXSD(childEl.Type) {
				fieldType = exportName(stripPrefix(childEl.Type), opts.MakePublic)
				isComplex = true
			}
		} else if childEl.Ref != "" {
			refName := stripPrefix(childEl.Ref)
			fieldName = exportName(refName, opts.MakePublic)
			fieldType = fieldName
			isComplex = true
		} else if childEl.ComplexType != nil {
			fieldType = renderInlineComplexType(*childEl.ComplexType, targetNS, opts, topAttrs)
		}

		if childEl.MaxOccurs == "unbounded" || childEl.MaxOccurs > "1" {
			if isComplex {
				fieldType = "[]*" + fieldType
			} else {
				fieldType = "[]" + fieldType
			}
		} else if isComplex && childEl.Type != "" {
			fieldType = "*" + fieldType
		}

		xmlTag := childEl.Name + ",omitempty"
		jsonTag := childEl.Name + ",omitempty"

		docComment := ""
		if childEl.Annotation != nil && childEl.Annotation.Documentation != "" {
			docComment = formatComment(childEl.Annotation.Documentation, "\t") + "\n"
		}

		fields = append(fields, fmt.Sprintf("%s\t%s %s `xml:%q json:%q`", docComment, fieldName, fieldType, xmlTag, jsonTag))
	}

	// Attributes
	attrs := ct.Attributes
	if ct.ComplexContent != nil && ct.ComplexContent.Extension != nil {
		attrs = append(attrs, ct.ComplexContent.Extension.Attributes...)
	}
	for _, attr := range attrs {
		attrName := attr.Name
		attrType := attr.Type
		if attr.Ref != "" {
			refName := stripPrefix(attr.Ref)
			attrName = refName
			if topAttr, ok := topAttrs[refName]; ok {
				attrType = topAttr.Type
			}
		}

		fieldName := exportName(attrName, opts.MakePublic)
		fieldType := mapXSDType(attrType)
		if attrType != "" && !isBuiltinXSD(attrType) {
			fieldType = exportName(stripPrefix(attrType), opts.MakePublic)
		}

		xmlTag := attrName + ",attr,omitempty"
		if targetNS != "" {
			xmlTag = fmt.Sprintf("%s %s,attr,omitempty", targetNS, attrName)
		}
		jsonTag := attrName + ",omitempty"

		docComment := ""
		if attr.Annotation != nil && attr.Annotation.Documentation != "" {
			docComment = formatComment(attr.Annotation.Documentation, "\t") + "\n"
		}

		fields = append(fields, fmt.Sprintf("%s\t%s %s `xml:%q json:%q`", docComment, fieldName, fieldType, xmlTag, jsonTag))
	}

	// SimpleContent
	if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
		ext := ct.SimpleContent.Extension
		fields = append(fields, "\tValue string `xml:\",chardata\" json:\"-,\"`")
		for _, attr := range ext.Attributes {
			attrName := attr.Name
			attrType := attr.Type
			if attr.Ref != "" {
				refName := stripPrefix(attr.Ref)
				attrName = refName
				if topAttr, ok := topAttrs[refName]; ok {
					attrType = topAttr.Type
				}
			}

			fieldName := exportName(attrName, opts.MakePublic)
			fieldType := mapXSDType(attrType)
			if attrType != "" && !isBuiltinXSD(attrType) {
				fieldType = exportName(stripPrefix(attrType), opts.MakePublic)
			}

			xmlTag := attrName + ",attr,omitempty"
			if targetNS != "" {
				xmlTag = fmt.Sprintf("%s %s,attr,omitempty", targetNS, attrName)
			}
			jsonTag := attrName + ",omitempty"

			docComment := ""
			if attr.Annotation != nil && attr.Annotation.Documentation != "" {
				docComment = formatComment(attr.Annotation.Documentation, "\t") + "\n"
			}

			fields = append(fields, fmt.Sprintf("%s\t%s %s `xml:%q json:%q`", docComment, fieldName, fieldType, xmlTag, jsonTag))
		}
	}

	code := fmt.Sprintf("type %s struct {\n%s\n}", typeName, strings.Join(fields, "\n\n"))
	return code
}

func renderInlineComplexType(ct wsdl.ComplexType, targetNS string, opts Options, topAttrs map[string]wsdl.Attribute) string {
	var fields []string
	elems := getComplexTypeElements(ct)

	for _, childEl := range elems {
		fieldName := exportName(childEl.Name, opts.MakePublic)
		fieldType := "string"
		if childEl.Type != "" {
			fieldType = mapXSDType(childEl.Type)
			if !isBuiltinXSD(childEl.Type) {
				fieldType = exportName(stripPrefix(childEl.Type), opts.MakePublic)
			}
		}

		if childEl.MaxOccurs == "unbounded" || childEl.MaxOccurs > "1" {
			fieldType = "[]" + fieldType
		}

		xmlTag := childEl.Name + ",omitempty"
		jsonTag := childEl.Name + ",omitempty"

		fields = append(fields, fmt.Sprintf("\t\t%s %s `xml:%q json:%q`", fieldName, fieldType, xmlTag, jsonTag))
	}

	if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
		ext := ct.SimpleContent.Extension
		fields = append(fields, "\t\tValue string `xml:\",chardata\" json:\"-,\"`")
		for _, attr := range ext.Attributes {
			attrName := attr.Name
			attrType := attr.Type
			if attr.Ref != "" {
				refName := stripPrefix(attr.Ref)
				attrName = refName
				if topAttr, ok := topAttrs[refName]; ok {
					attrType = topAttr.Type
				}
			}

			fieldName := exportName(attrName, opts.MakePublic)
			fieldType := mapXSDType(attrType)
			if attrType != "" && !isBuiltinXSD(attrType) {
				fieldType = exportName(stripPrefix(attrType), opts.MakePublic)
			}

			xmlTag := attrName + ",attr,omitempty"
			if targetNS != "" {
				xmlTag = fmt.Sprintf("%s %s,attr,omitempty", targetNS, attrName)
			}
			jsonTag := attrName + ",omitempty"

			docComment := ""
			if attr.Annotation != nil && attr.Annotation.Documentation != "" {
				docComment = formatComment(attr.Annotation.Documentation, "\t\t") + "\n"
			}

			fields = append(fields, fmt.Sprintf("%s\t\t%s %s `xml:%q json:%q`", docComment, fieldName, fieldType, xmlTag, jsonTag))
		}
	}

	return fmt.Sprintf("struct {\n%s\n\t}", strings.Join(fields, "\n\n"))
}

func injectXMLName(structCode string, xmlNameTag string) string {
	xmlLine := fmt.Sprintf("\tXMLName xml.Name `xml:%q`", xmlNameTag)
	idx := strings.Index(structCode, "struct {")
	if idx != -1 {
		insertAt := idx + len("struct {")
		return structCode[:insertAt] + "\n" + xmlLine + "\n" + structCode[insertAt:]
	}
	return structCode
}

func formatComment(text string, indent string) string {
	if strings.TrimSpace(text) == "" {
		return ""
	}
	lines := strings.Split(text, "\n")
	var formatted []string
	for _, l := range lines {
		trimmed := strings.TrimSpace(l)
		if strings.HasPrefix(trimmed, "//") {
			trimmed = strings.TrimSpace(strings.TrimPrefix(trimmed, "//"))
		}
		if trimmed == "" {
			formatted = append(formatted, indent+"//")
		} else {
			formatted = append(formatted, fmt.Sprintf("%s// %s", indent, trimmed))
		}
	}
	return strings.Join(formatted, "\n")
}

func mapXSDType(xsdType string) string {
	raw := stripPrefix(xsdType)
	switch raw {
	case "string", "normalizedString", "token", "language", "Name", "NCName", "NMTOKEN", "ID", "IDREF":
		return "string"
	case "boolean":
		return "bool"
	case "int":
		return "int32"
	case "integer", "positiveInteger", "negativeInteger", "nonPositiveInteger", "nonNegativeInteger":
		return "int"
	case "long":
		return "int64"
	case "short":
		return "int16"
	case "byte":
		return "int8"
	case "unsignedInt":
		return "uint32"
	case "unsignedLong":
		return "uint64"
	case "unsignedShort":
		return "uint16"
	case "unsignedByte":
		return "byte"
	case "float":
		return "float32"
	case "double", "decimal":
		return "float64"
	case "dateTime":
		return "soap.XSDDateTime"
	case "date":
		return "soap.XSDDate"
	case "time":
		return "soap.XSDTime"
	case "duration":
		return "string"
	case "anyURI":
		return "AnyURI"
	case "base64Binary", "hexBinary":
		return "[]byte"
	case "anyType":
		return "AnyType"
	default:
		return raw
	}
}

func isBuiltinXSD(xsdType string) bool {
	raw := stripPrefix(xsdType)
	switch raw {
	case "string", "normalizedString", "token", "language", "Name", "NCName", "NMTOKEN", "ID", "IDREF",
		"boolean", "int", "integer", "positiveInteger", "negativeInteger", "nonPositiveInteger", "nonNegativeInteger",
		"long", "short", "byte", "unsignedInt", "unsignedLong", "unsignedShort", "unsignedByte",
		"float", "double", "decimal", "dateTime", "date", "time", "duration", "anyURI", "base64Binary", "hexBinary", "anyType":
		return true
	default:
		return false
	}
}

func stripPrefix(s string) string {
	if idx := strings.Index(s, ":"); idx != -1 {
		return s[idx+1:]
	}
	return s
}

func sanitizeEnumVal(s string) string {
	if s == "" {
		return "EmptyString"
	}
	var sb strings.Builder
	capitalizeNext := true
	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			if capitalizeNext {
				sb.WriteRune(unicode.ToUpper(r))
				capitalizeNext = false
			} else {
				sb.WriteRune(r)
			}
		} else if r == '_' {
			sb.WriteRune('_')
			capitalizeNext = true
		} else {
			capitalizeNext = true
		}
	}
	res := sb.String()
	if len(res) > 0 && unicode.IsDigit(rune(res[0])) {
		res = "Val" + res
	}
	return res
}

func exportName(s string, makePublic bool) string {
	if s == "" {
		return ""
	}
	clean := sanitizeIdentifier(s)
	if goKeywords[strings.ToLower(clean)] {
		clean = clean + "_"
	}
	if makePublic {
		return capitalize(clean)
	}
	return uncapitalize(clean)
}

func unexportName(s string, makePublic bool) string {
	if s == "" {
		return ""
	}
	clean := sanitizeIdentifier(s)
	if goKeywords[strings.ToLower(clean)] {
		clean = clean + "_"
	}
	return uncapitalize(clean)
}

func sanitizeIdentifier(s string) string {
	reg := regexp.MustCompile("[^a-zA-Z0-9_]+")
	clean := reg.ReplaceAllString(s, "_")
	return clean
}

func capitalize(s string) string {
	if s == "" {
		return ""
	}
	r := []rune(s)
	r[0] = unicode.ToUpper(r[0])
	return string(r)
}

func uncapitalize(s string) string {
	if s == "" {
		return ""
	}
	r := []rune(s)
	r[0] = unicode.ToLower(r[0])
	return string(r)
}
EOF
"}

actions.command:
cat << 'EOF' > generator/generator.go
package generator

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"text/template"
	"unicode"

	"github.com/hooklift/gowsdl/wsdl"
)

type Options struct {
	Pkg        string
	Outfile    string
	Dir        string
	MakePublic bool
}

type TypeModel struct {
	Name string
	Code string
}

type OperationModel struct {
	Name          string
	RequestType   string
	ResponseType  string
	SoapAction    string
	Documentation string
}

type PortTypeModel struct {
	InterfaceName string
	StructName    string
	Operations    []OperationModel
}

type ServerOperationModel struct {
	ReqType  string
	RespType string
}

type ClientData struct {
	PackageName string
	Types       []TypeModel
	PortTypes   []PortTypeModel
}

type ServerData struct {
	PackageName      string
	RawWSDL          string
	ServerOperations []ServerOperationModel
}

var goKeywords = map[string]bool{
	"break": true, "default": true, "func": true, "interface": true, "select": true,
	"case": true, "defer": true, "go": true, "map": true, "struct": true,
	"chan": true, "else": true, "goto": true, "package": true, "switch": true,
	"const": true, "fallthrough": true, "if": true, "range": true, "type": true,
	"continue": true, "for": true, "import": true, "return": true, "var": true,
}

func Generate(pw *wsdl.ParsedWSDL, opts Options) error {
	clientData := ClientData{
		PackageName: opts.Pkg,
	}

	serverData := ServerData{
		PackageName: opts.Pkg,
		RawWSDL:     pw.RawWSDL,
	}

	typeModels, elementToTypeMap := processTypes(pw, opts)
	clientData.Types = typeModels

	msgToType := make(map[string]string)
	for _, msg := range pw.Definitions.Messages {
		if len(msg.Parts) == 0 {
			fmt.Printf("🍀  [WARN] %s message doesn't have any parts, ignoring message...\n", msg.Name)
			continue
		}
		part := msg.Parts[0]
		rawName := ""
		if part.Element != "" {
			rawName = stripPrefix(part.Element)
		} else if part.Type != "" {
			rawName = stripPrefix(part.Type)
		}

		if mapped, ok := elementToTypeMap[rawName]; ok {
			msgToType[msg.Name] = mapped
		} else {
			msgToType[msg.Name] = exportName(rawName, opts.MakePublic)
		}
	}

	opToSoapAction := make(map[string]string)
	for _, b := range pw.Definitions.Bindings {
		for _, bo := range b.BindingOperations {
			action := bo.SoapOperation.SoapAction
			if action == "" {
				action = "''"
			}
			opToSoapAction[bo.Name] = action
		}
	}

	serverOpSet := make(map[string]bool)

	for _, pt := range pw.Definitions.PortTypes {
		ptModel := PortTypeModel{
			InterfaceName: exportName(pt.Name, opts.MakePublic),
			StructName:    unexportName(pt.Name, opts.MakePublic),
		}

		for _, op := range pt.Operations {
			reqMsg := stripPrefix(op.Input.Message)
			respMsg := stripPrefix(op.Output.Message)

			reqType, okReq := msgToType[reqMsg]
			respType, okResp := msgToType[respMsg]

			if !okReq || !okResp {
				continue
			}

			action := opToSoapAction[op.Name]
			if action == "" {
				action = "''"
			}

			doc := formatComment(op.Documentation, "")

			opModel := OperationModel{
				Name:          exportName(op.Name, opts.MakePublic),
				RequestType:   reqType,
				ResponseType:  respType,
				SoapAction:    action,
				Documentation: doc,
			}
			ptModel.Operations = append(ptModel.Operations, opModel)

			opKey := reqType + "->" + respType
			if !serverOpSet[opKey] {
				serverOpSet[opKey] = true
				serverData.ServerOperations = append(serverData.ServerOperations, ServerOperationModel{
					ReqType:  reqType,
					RespType: respType,
				})
			}
		}

		clientData.PortTypes = append(clientData.PortTypes, ptModel)
	}

	tmplClient, err := template.New("client").Parse(ClientTemplate)
	if err != nil {
		return err
	}
	var bufClient bytes.Buffer
	if err := tmplClient.Execute(&bufClient, clientData); err != nil {
		return err
	}

	formattedClient, err := format.Source(bufClient.Bytes())
	if err != nil {
		formattedClient = bufClient.Bytes()
	}

	tmplServer, err := template.New("server").Parse(ServerTemplate)
	if err != nil {
		return err
	}
	var bufServer bytes.Buffer
	if err := tmplServer.Execute(&bufServer, serverData); err != nil {
		return err
	}

	formattedServer, err := format.Source(bufServer.Bytes())
	if err != nil {
		formattedServer = bufServer.Bytes()
	}

	outPath := filepath.Join(opts.Dir, opts.Pkg, opts.Outfile)
	serverOutPath := filepath.Join(opts.Dir, opts.Pkg, "server"+filepath.Base(opts.Outfile))

	if err := writeFile(outPath, formattedClient); err != nil {
		return err
	}
	if err := writeFile(serverOutPath, formattedServer); err != nil {
		return err
	}

	return nil
}

func writeFile(path string, content []byte) error {
	return os.WriteFile(path, content, 0644)
}

func processTypes(pw *wsdl.ParsedWSDL, opts Options) ([]TypeModel, map[string]string) {
	var models []TypeModel
	elementToTypeMap := make(map[string]string)

	schemas := pw.Definitions.Types.Schemas

	topAttrs := make(map[string]wsdl.Attribute)
	elementToComplexTypeXMLName := make(map[string]string)

	for _, s := range schemas {
		targetNS := s.TargetNamespace
		for _, attr := range s.Attributes {
			if attr.Name != "" {
				topAttrs[attr.Name] = attr
			}
		}
		for _, el := range s.Elements {
			if el.Name != "" && el.Type != "" && !isBuiltinXSD(el.Type) {
				ctName := exportName(stripPrefix(el.Type), opts.MakePublic)
				xmlTag := fmt.Sprintf("%s %s", targetNS, el.Name)
				if targetNS == "" {
					xmlTag = el.Name
				}
				elementToComplexTypeXMLName[ctName] = xmlTag
			}
		}
	}

	for _, s := range schemas {
		targetNS := s.TargetNamespace

		// 1. SimpleTypes (FIRST)
		for _, st := range s.SimpleTypes {
			if st.Name == "" {
				continue
			}
			typeName := exportName(st.Name, opts.MakePublic)
			doc := ""
			if st.Annotation != nil {
				doc = formatComment(st.Annotation.Documentation, "")
			}

			if st.Restriction != nil && len(st.Restriction.Enumerations) > 0 {
				var enumLines []string
				for _, enum := range st.Restriction.Enumerations {
					enumVal := enum.Value
					constName := typeName + sanitizeEnumVal(enumVal)
					enumDoc := ""
					if enum.Annotation != nil && enum.Annotation.Documentation != "" {
						enumDoc = formatComment(enum.Annotation.Documentation, "\t") + "\n"
					}
					enumLines = append(enumLines, fmt.Sprintf("%s\t%s %s = %q", enumDoc, constName, typeName, enumVal))
				}

				code := fmt.Sprintf("type %s string\n\nconst (\n%s\n)", typeName, strings.Join(enumLines, "\n\n"))
				if doc != "" {
					code = fmt.Sprintf("// %s\ntype %s string\n\nconst (\n%s\n)", doc, typeName, strings.Join(enumLines, "\n\n"))
				}
				models = append(models, TypeModel{Name: typeName, Code: code})
			} else if st.Restriction != nil {
				base := mapXSDType(st.Restriction.Base)
				if base == "soap.XSDDateTime" || base == "soap.XSDDate" {
					code := fmt.Sprintf("type %s %s\n\nfunc (xdt %s) MarshalXML(e *xml.Encoder, start xml.StartElement) error {\n\treturn %s(xdt).MarshalXML(e, start)\n}\n\nfunc (xdt *%s) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {\n\treturn (*%s)(xdt).UnmarshalXML(d, start)\n}", typeName, base, typeName, base, typeName, base)
					models = append(models, TypeModel{Name: typeName, Code: code})
				} else {
					code := fmt.Sprintf("type %s %s", typeName, base)
					models = append(models, TypeModel{Name: typeName, Code: code})
				}
			}
		}

		// 2. Elements
		for _, el := range s.Elements {
			if el.Name == "" {
				continue
			}
			elemName := exportName(el.Name, opts.MakePublic)

			if el.ComplexType != nil {
				code := renderComplexType(*el.ComplexType, elemName, targetNS, opts, topAttrs)
				xmlNameTag := fmt.Sprintf("%s %s", targetNS, el.Name)
				if targetNS == "" {
					xmlNameTag = el.Name
				}
				code = injectXMLName(code, xmlNameTag)
				models = append(models, TypeModel{Name: elemName, Code: code})
			} else if el.SimpleType != nil {
				if el.SimpleType.Restriction != nil && len(el.SimpleType.Restriction.Enumerations) > 0 {
					var enumLines []string
					for _, enum := range el.SimpleType.Restriction.Enumerations {
						enumVal := enum.Value
						constName := elemName + sanitizeEnumVal(enumVal)
						enumDoc := ""
						if enum.Annotation != nil && enum.Annotation.Documentation != "" {
							enumDoc = formatComment(enum.Annotation.Documentation, "\t") + "\n"
						}
						enumLines = append(enumLines, fmt.Sprintf("%s\t%s %s = %q", enumDoc, constName, elemName, enumVal))
					}
					doc := ""
					if el.Annotation != nil {
						doc = formatComment(el.Annotation.Documentation, "")
					}
					code := fmt.Sprintf("type %s string\n\nconst (\n%s\n)", elemName, strings.Join(enumLines, "\n\n"))
					if doc != "" {
						code = fmt.Sprintf("// %s\ntype %s string\n\nconst (\n%s\n)", doc, elemName, strings.Join(enumLines, "\n\n"))
					}
					models = append(models, TypeModel{Name: elemName, Code: code})
				}
			} else if el.Type != "" {
				rawType := stripPrefix(el.Type)
				mappedType := mapXSDType(el.Type)

				if isBuiltinXSD(el.Type) {
					if mappedType == "soap.XSDDateTime" || mappedType == "soap.XSDDate" {
						code := fmt.Sprintf("type %s %s\n\nfunc (xdt %s) MarshalXML(e *xml.Encoder, start xml.StartElement) error {\n\treturn %s(xdt).MarshalXML(e, start)\n}\n\nfunc (xdt *%s) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {\n\treturn (*%s)(xdt).UnmarshalXML(d, start)\n}", elemName, mappedType, elemName, mappedType, elemName, mappedType)
						models = append(models, TypeModel{Name: elemName, Code: code})
					} else {
						code := fmt.Sprintf("type %s %s", elemName, mappedType)
						models = append(models, TypeModel{Name: elemName, Code: code})
					}
				} else {
					targetType := exportName(rawType, opts.MakePublic)
					elementToTypeMap[el.Name] = targetType
					if elemName != targetType {
						code := fmt.Sprintf("type %s %s", elemName, targetType)
						models = append(models, TypeModel{Name: elemName, Code: code})
					}
				}
			}
		}

		// 3. ComplexTypes
		for _, ct := range s.ComplexTypes {
			if ct.Name == "" {
				continue
			}
			typeName := exportName(ct.Name, opts.MakePublic)
			code := renderComplexType(ct, typeName, targetNS, opts, topAttrs)

			if xmlTag, ok := elementToComplexTypeXMLName[typeName]; ok {
				code = injectXMLName(code, xmlTag)
			}

			models = append(models, TypeModel{Name: typeName, Code: code})
		}
	}

	return models, elementToTypeMap
}

func getComplexTypeElements(ct wsdl.ComplexType) []wsdl.Element {
	var elems []wsdl.Element
	if ct.Sequence != nil {
		elems = append(elems, ct.Sequence.Elements...)
	}
	if ct.All != nil {
		elems = append(elems, ct.All.Elements...)
	}
	if ct.Choice != nil {
		elems = append(elems, ct.Choice.Elements...)
	}
	return elems
}

func renderComplexType(ct wsdl.ComplexType, typeName string, targetNS string, opts Options, topAttrs map[string]wsdl.Attribute) string {
	var fields []string

	elems := getComplexTypeElements(ct)

	if ct.ComplexContent != nil {
		if ct.ComplexContent.Extension != nil {
			ext := ct.ComplexContent.Extension
			baseType := exportName(stripPrefix(ext.Base), opts.MakePublic)
			fields = append(fields, fmt.Sprintf("\t*%s", baseType))
			if ext.Sequence != nil {
				elems = append(elems, ext.Sequence.Elements...)
			}
			if ext.All != nil {
				elems = append(elems, ext.All.Elements...)
			}
			if ext.Choice != nil {
				elems = append(elems, ext.Choice.Elements...)
			}
		}
	}

	for _, childEl := range elems {
		fieldName := exportName(childEl.Name, opts.MakePublic)
		fieldType := "string"
		isComplex := false

		if childEl.Type != "" {
			fieldType = mapXSDType(childEl.Type)
			if !isBuiltinXSD(childEl.Type) {
				fieldType = exportName(stripPrefix(childEl.Type), opts.MakePublic)
				isComplex = true
			}
		} else if childEl.Ref != "" {
			refName := stripPrefix(childEl.Ref)
			fieldName = exportName(refName, opts.MakePublic)
			fieldType = fieldName
			isComplex = true
		} else if childEl.ComplexType != nil {
			fieldType = renderInlineComplexType(*childEl.ComplexType, targetNS, opts, topAttrs)
		}

		if childEl.MaxOccurs == "unbounded" || childEl.MaxOccurs > "1" {
			if isComplex {
				fieldType = "[]*" + fieldType
			} else {
				fieldType = "[]" + fieldType
			}
		} else if isComplex && childEl.Type != "" {
			fieldType = "*" + fieldType
		}

		xmlTag := childEl.Name + ",omitempty"
		jsonTag := childEl.Name + ",omitempty"

		docComment := ""
		if childEl.Annotation != nil && childEl.Annotation.Documentation != "" {
			docComment = formatComment(childEl.Annotation.Documentation, "\t") + "\n"
		}

		fields = append(fields, fmt.Sprintf("%s\t%s %s `xml:%q json:%q`", docComment, fieldName, fieldType, xmlTag, jsonTag))
	}

	// Attributes
	attrs := ct.Attributes
	if ct.ComplexContent != nil && ct.ComplexContent.Extension != nil {
		attrs = append(attrs, ct.ComplexContent.Extension.Attributes...)
	}
	for _, attr := range attrs {
		attrName := attr.Name
		attrType := attr.Type
		if attr.Ref != "" {
			refName := stripPrefix(attr.Ref)
			attrName = refName
			if topAttr, ok := topAttrs[refName]; ok {
				attrType = topAttr.Type
			}
		}

		fieldName := exportName(attrName, opts.MakePublic)
		fieldType := mapXSDType(attrType)
		if attrType != "" && !isBuiltinXSD(attrType) {
			fieldType = exportName(stripPrefix(attrType), opts.MakePublic)
		}

		xmlTag := attrName + ",attr,omitempty"
		if targetNS != "" {
			xmlTag = fmt.Sprintf("%s %s,attr,omitempty", targetNS, attrName)
		}
		jsonTag := attrName + ",omitempty"

		docComment := ""
		if attr.Annotation != nil && attr.Annotation.Documentation != "" {
			docComment = formatComment(attr.Annotation.Documentation, "\t") + "\n"
		}

		fields = append(fields, fmt.Sprintf("%s\t%s %s `xml:%q json:%q`", docComment, fieldName, fieldType, xmlTag, jsonTag))
	}

	// SimpleContent
	if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
		ext := ct.SimpleContent.Extension
		fields = append(fields, "\tValue string `xml:\",chardata\" json:\"-,\"`")
		for _, attr := range ext.Attributes {
			attrName := attr.Name
			attrType := attr.Type
			if attr.Ref != "" {
				refName := stripPrefix(attr.Ref)
				attrName = refName
				if topAttr, ok := topAttrs[refName]; ok {
					attrType = topAttr.Type
				}
			}

			fieldName := exportName(attrName, opts.MakePublic)
			fieldType := mapXSDType(attrType)
			if attrType != "" && !isBuiltinXSD(attrType) {
				fieldType = exportName(stripPrefix(attrType), opts.MakePublic)
			}

			xmlTag := attrName + ",attr,omitempty"
			if targetNS != "" {
				xmlTag = fmt.Sprintf("%s %s,attr,omitempty", targetNS, attrName)
			}
			jsonTag := attrName + ",omitempty"

			docComment := ""
			if attr.Annotation != nil && attr.Annotation.Documentation != "" {
				docComment = formatComment(attr.Annotation.Documentation, "\t") + "\n"
			}

			fields = append(fields, fmt.Sprintf("%s\t%s %s `xml:%q json:%q`", docComment, fieldName, fieldType, xmlTag, jsonTag))
		}
	}

	code := fmt.Sprintf("type %s struct {\n%s\n}", typeName, strings.Join(fields, "\n\n"))
	return code
}

func renderInlineComplexType(ct wsdl.ComplexType, targetNS string, opts Options, topAttrs map[string]wsdl.Attribute) string {
	var fields []string
	elems := getComplexTypeElements(ct)

	for _, childEl := range elems {
		fieldName := exportName(childEl.Name, opts.MakePublic)
		fieldType := "string"
		if childEl.Type != "" {
			fieldType = mapXSDType(childEl.Type)
			if !isBuiltinXSD(childEl.Type) {
				fieldType = exportName(stripPrefix(childEl.Type), opts.MakePublic)
			}
		}

		if childEl.MaxOccurs == "unbounded" || childEl.MaxOccurs > "1" {
			fieldType = "[]" + fieldType
		}

		xmlTag := childEl.Name + ",omitempty"
		jsonTag := childEl.Name + ",omitempty"

		fields = append(fields, fmt.Sprintf("\t\t%s %s `xml:%q json:%q`", fieldName, fieldType, xmlTag, jsonTag))
	}

	if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
		ext := ct.SimpleContent.Extension
		fields = append(fields, "\t\tValue string `xml:\",chardata\" json:\"-,\"`")
		for _, attr := range ext.Attributes {
			attrName := attr.Name
			attrType := attr.Type
			if attr.Ref != "" {
				refName := stripPrefix(attr.Ref)
				attrName = refName
				if topAttr, ok := topAttrs[refName]; ok {
					attrType = topAttr.Type
				}
			}

			fieldName := exportName(attrName, opts.MakePublic)
			fieldType := mapXSDType(attrType)
			if attrType != "" && !isBuiltinXSD(attrType) {
				fieldType = exportName(stripPrefix(attrType), opts.MakePublic)
			}

			xmlTag := attrName + ",attr,omitempty"
			if targetNS != "" {
				xmlTag = fmt.Sprintf("%s %s,attr,omitempty", targetNS, attrName)
			}
			jsonTag := attrName + ",omitempty"

			docComment := ""
			if attr.Annotation != nil && attr.Annotation.Documentation != "" {
				docComment = formatComment(attr.Annotation.Documentation, "\t\t") + "\n"
			}

			fields = append(fields, fmt.Sprintf("%s\t\t%s %s `xml:%q json:%q`", docComment, fieldName, fieldType, xmlTag, jsonTag))
		}
	}

	return fmt.Sprintf("struct {\n%s\n\t}", strings.Join(fields, "\n\n"))
}

func injectXMLName(structCode string, xmlNameTag string) string {
	xmlLine := fmt.Sprintf("\tXMLName xml.Name `xml:%q`", xmlNameTag)
	idx := strings.Index(structCode, "struct {")
	if idx != -1 {
		insertAt := idx + len("struct {")
		return structCode[:insertAt] + "\n" + xmlLine + "\n" + structCode[insertAt:]
	}
	return structCode
}

func formatComment(text string, indent string) string {
	if strings.TrimSpace(text) == "" {
		return ""
	}
	lines := strings.Split(text, "\n")
	var formatted []string
	for _, l := range lines {
		trimmed := strings.TrimSpace(l)
		if strings.HasPrefix(trimmed, "//") {
			trimmed = strings.TrimSpace(strings.TrimPrefix(trimmed, "//"))
		}
		if trimmed == "" {
			formatted = append(formatted, indent+"//")
		} else {
			formatted = append(formatted, fmt.Sprintf("%s// %s", indent, trimmed))
		}
	}
	return strings.Join(formatted, "\n")
}

func mapXSDType(xsdType string) string {
	raw := stripPrefix(xsdType)
	switch raw {
	case "string", "normalizedString", "token", "language", "Name", "NCName", "NMTOKEN", "ID", "IDREF":
		return "string"
	case "boolean":
		return "bool"
	case "int":
		return "int32"
	case "integer", "positiveInteger", "negativeInteger", "nonPositiveInteger", "nonNegativeInteger":
		return "int"
	case "long":
		return "int64"
	case "short":
		return "int16"
	case "byte":
		return "int8"
	case "unsignedInt":
		return "uint32"
	case "unsignedLong":
		return "uint64"
	case "unsignedShort":
		return "uint16"
	case "unsignedByte":
		return "byte"
	case "float":
		return "float32"
	case "double", "decimal":
		return "float64"
	case "dateTime":
		return "soap.XSDDateTime"
	case "date":
		return "soap.XSDDate"
	case "time":
		return "soap.XSDTime"
	case "duration":
		return "string"
	case "anyURI":
		return "AnyURI"
	case "base64Binary", "hexBinary":
		return "[]byte"
	case "anyType":
		return "AnyType"
	default:
		return raw
	}
}

func isBuiltinXSD(xsdType string) bool {
	raw := stripPrefix(xsdType)
	switch raw {
	case "string", "normalizedString", "token", "language", "Name", "NCName", "NMTOKEN", "ID", "IDREF",
		"boolean", "int", "integer", "positiveInteger", "negativeInteger", "nonPositiveInteger", "nonNegativeInteger",
		"long", "short", "byte", "unsignedInt", "unsignedLong", "unsignedShort", "unsignedByte",
		"float", "double", "decimal", "dateTime", "date", "time", "duration", "anyURI", "base64Binary", "hexBinary", "anyType":
		return true
	default:
		return false
	}
}

func stripPrefix(s string) string {
	if idx := strings.Index(s, ":"); idx != -1 {
		return s[idx+1:]
	}
	return s
}

func sanitizeEnumVal(s string) string {
	if s == "" {
		return "EmptyString"
	}
	var sb strings.Builder
	capitalizeNext := true
	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			if capitalizeNext {
				sb.WriteRune(unicode.ToUpper(r))
				capitalizeNext = false
			} else {
				sb.WriteRune(r)
			}
		} else if r == '_' {
			sb.WriteRune('_')
			capitalizeNext = true
		} else {
			capitalizeNext = true
		}
	}
	res := sb.String()
	if len(res) > 0 && unicode.IsDigit(rune(res[0])) {
		res = "Val" + res
	}
	return res
}

func exportName(s string, makePublic bool) string {
	if s == "" {
		return ""
	}
	clean := sanitizeIdentifier(s)
	if goKeywords[strings.ToLower(clean)] {
		clean = clean + "_"
	}
	if makePublic {
		return capitalize(clean)
	}
	return uncapitalize(clean)
}

func unexportName(s string, makePublic bool) string {
	if s == "" {
		return ""
	}
	clean := sanitizeIdentifier(s)
	if goKeywords[strings.ToLower(clean)] {
		clean = clean + "_"
	}
	return uncapitalize(clean)
}

func sanitizeIdentifier(s string) string {
	reg := regexp.MustCompile("[^a-zA-Z0-9_]+")
	clean := reg.ReplaceAllString(s, "_")
	return clean
}

func capitalize(s string) string {
	if s == "" {
		return ""
	}
	r := []rune(s)
	r[0] = unicode.ToUpper(r[0])
	return string(r)
}

func uncapitalize(s string) string {
	if s == "" {
		return ""
	}
	r := []rune(s)
	r[0] = unicode.ToLower(r[0])
	return string(r)
}
